'use client';

import { cn } from '@/lib/utils';
import { motion, useTime, useTransform } from 'motion/react';
import React, { useId } from 'react';

export interface SquigglyTextProps {
    /**
     * The text (or any node) to wrap with the squiggly effect.
     */
    children: React.ReactNode;
    className?: string;
    style?: React.CSSProperties;
    /**
     * Number of distinct displacement frames to cycle through.
     * Higher = smoother wobble, more SVG filters in the DOM.
     * @default 5
     */
    steps?: number;
    /**
     * Time between filter swaps, in milliseconds.
     * Lower = more frantic; higher = lazier wave.
     * @default 80
     */
    stepDuration?: number;
    /**
     * Maximum displacement in px. Bigger = more squiggly.
     * Pass a single number for a constant scale, or a tuple to alternate
     * between two values per step (matches the original Lucas Bebber demo).
     * @default [6, 8]
     */
    scale?: number | [number, number];
    /**
     * Turbulence base frequency. Lower values produce longer, smoother waves;
     * higher values produce tighter, jitterier noise.
     * @default 0.02
     */
    baseFrequency?: number;
    /**
     * Number of turbulence octaves. Higher = more detailed noise.
     * @default 3
     */
    numOctaves?: number;
    /**
     * Render the wrapper as this element type.
     * @default "span"
     */
    as?: 'span' | 'div';
}

/**
 * This funciton renders the {@link SquigglyText} text block component.
 *
 * @author Aayush Goyal
 * @version 0.1.0
 * @created 2026-09-19
 */
export function SquigglyText({
    children,
    steps = 5,
    stepDuration = 80,
    scale = [6, 8],
    baseFrequency = 0.02,
    numOctaves = 3,
    as = 'span',
    className,
    style
}: SquigglyTextProps) {
    const reactId = useId();
    // useId can produce ":" / "_" which aren't valid in CSS url(#…) refs.
    const safeId = reactId.replace(/[:_]/g, '');
    const filterId = (i: number) => `squiggly-${safeId}-${i}`;

    const filters = React.useMemo(
        () => Array.from({ length: steps }, (_, i) => `url(#${filterId(i)})`),
        // filterId is stable per render
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [steps, safeId]
    );

    const time = useTime();
    const filter = useTransform(
        time,
        (t) => filters[Math.floor(t / stepDuration) % filters.length]
    );

    const scaleAt = (i: number) =>
        Array.isArray(scale) ? scale[i % scale.length] : scale;

    const Wrapper = as === 'div' ? motion.div : motion.span;

    return (
        <Wrapper
            style={{ filter, ...style }}
            className={cn('inline-block', className)}
        >
            <svg
                aria-hidden
                className="pointer-events-none absolute h-0 w-0 overflow-hidden"
                xmlns="http://www.w3.org/2000/svg"
            >
                <defs>
                    {Array.from({ length: steps }).map((_, i) => (
                        <filter id={filterId(i)} key={i}>
                            <feTurbulence
                                baseFrequency={baseFrequency}
                                numOctaves={numOctaves}
                                result="noise"
                                seed={i}
                            />
                            <feDisplacementMap
                                in="SourceGraphic"
                                in2="noise"
                                scale={scaleAt(i)}
                            />
                        </filter>
                    ))}
                </defs>
            </svg>
            {children}
        </Wrapper>
    );
}

'use client';

import {
    getDataFromLocalStorage,
    setDataInLocalStorage
} from '@/lib/local-storage';
import useUserPreferenceStore from '@/lib/store/user-preference-store';
import { THEME } from '@/lib/types/enums';
import { ToggleGroup, ToggleGroupItem } from '@/src/components/toggle-group';
import { Monitor, Moon, Sun } from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { flushSync } from 'react-dom';

export type TransitionVariant =
    | 'circle'
    | 'square'
    | 'triangle'
    | 'diamond'
    | 'hexagon'
    | 'rectangle'
    | 'star';

/**
 * Applies or removes the 'dark' class on the root HTML element.
 */
const applyThemeToDocument = (themeValue: string) => {
    const htmlElement = document.documentElement;
    if (themeValue === 'system') {
        const isSystemDark = window.matchMedia(
            '(prefers-color-scheme: dark)'
        ).matches;
        htmlElement.classList.toggle('dark', isSystemDark);
    } else {
        htmlElement.classList.toggle('dark', themeValue === 'dark');
    }
};

/**
 * This function renders the Theme Switcher component of the app.
 *
 * @version 0.1.0
 * @author Aayush Goyal
 * @created 2026-09-19
 */
export default function ThemeSwitcher({
    duration = 500,
    fromCenter = false,
    variant = 'circle',
    onThemeChange
}: {
    duration?: number;
    fromCenter?: boolean;
    variant?: TransitionVariant;
    onThemeChange?: (theme: THEME) => void;
}) {
    // SECTION: Constants and Variables
    const buttonRef = useRef<HTMLDivElement>(null);
    const isTransitioningRef = useRef(false);
    const shape = variant ?? 'circle';
    const { theme, actions } = useUserPreferenceStore();
    const isControlled = theme !== undefined;
    // !SECTION: Constants and Variables

    // SECTION: States
    const [internalIsDark, setInternalIsDark] = useState(false);
    const isDark = isControlled ? theme === THEME.GUN_METAL : internalIsDark;
    // !SECTION: States

    // SECTION: Functions
    function polygonCollapsed(point: string, vertexCount: number): string {
        const pairs = Array.from({ length: vertexCount }, () => point).join(
            ', '
        );
        return `polygon(${pairs})`;
    }

    function getThemeTransitionClipPaths(
        variant: TransitionVariant,
        cx: number,
        cy: number,
        maxRadius: number,
        viewportWidth: number,
        viewportHeight: number
    ): [string, string] {
        const toX = (x: number) => `${(x / viewportWidth) * 100}%`;
        const toY = (y: number) => `${(y / viewportHeight) * 100}%`;
        const point = (x: number, y: number) => `${toX(x)} ${toY(y)}`;
        const toRadius = (r: number) =>
            `${(r / (Math.hypot(viewportWidth, viewportHeight) / Math.SQRT2)) * 100}%`;

        switch (variant) {
            case 'circle':
                return [
                    `circle(0% at ${point(cx, cy)})`,
                    `circle(${toRadius(maxRadius)} at ${point(cx, cy)})`
                ];
            case 'square': {
                const halfW = Math.max(cx, viewportWidth - cx);
                const halfH = Math.max(cy, viewportHeight - cy);
                const halfSide = Math.max(halfW, halfH) * 1.05;
                const end = [
                    point(cx - halfSide, cy - halfSide),
                    point(cx + halfSide, cy - halfSide),
                    point(cx + halfSide, cy + halfSide),
                    point(cx - halfSide, cy + halfSide)
                ].join(', ');
                return [polygonCollapsed(point(cx, cy), 4), `polygon(${end})`];
            }
            case 'triangle': {
                const scale = maxRadius * 2.2;
                const dx = (Math.sqrt(3) / 2) * scale;
                const verts = [
                    point(cx, cy - scale),
                    point(cx + dx, cy + 0.5 * scale),
                    point(cx - dx, cy + 0.5 * scale)
                ].join(', ');
                return [
                    polygonCollapsed(point(cx, cy), 3),
                    `polygon(${verts})`
                ];
            }
            case 'diamond': {
                const R = maxRadius * Math.SQRT2;
                const end = [
                    point(cx, cy - R),
                    point(cx + R, cy),
                    point(cx + R, cy + R),
                    point(cx - R, cy)
                ].join(', ');
                return [polygonCollapsed(point(cx, cy), 4), `polygon(${end})`];
            }
            case 'hexagon': {
                const R = maxRadius * Math.SQRT2;
                const verts: string[] = [];
                for (let i = 0; i < 6; i++) {
                    const a = -Math.PI / 2 + (i * Math.PI) / 3;
                    verts.push(
                        point(cx + R * Math.cos(a), cy + R * Math.sin(a))
                    );
                }
                return [
                    polygonCollapsed(point(cx, cy), 6),
                    `polygon(${verts.join(', ')})`
                ];
            }
            case 'rectangle': {
                const halfW = Math.max(cx, viewportWidth - cx);
                const halfH = Math.max(cy, viewportHeight - cy);
                const end = [
                    point(cx - halfW, cy - halfH),
                    point(cx + halfW, cy - halfH),
                    point(cx + halfW, cy + halfH),
                    point(cx - halfW, cy + halfH)
                ].join(', ');
                return [polygonCollapsed(point(cx, cy), 4), `polygon(${end})`];
            }
            case 'star': {
                const R = maxRadius * Math.SQRT2 * 1.03;
                const innerRatio = 0.42;
                const starPolygon = (radius: number) => {
                    const verts: string[] = [];
                    for (let i = 0; i < 5; i++) {
                        const outerA = -Math.PI / 2 + (i * 2 * Math.PI) / 5;
                        verts.push(
                            point(
                                cx + radius * Math.cos(outerA),
                                cy + radius * Math.sin(outerA)
                            )
                        );
                        const innerA = outerA + Math.PI / 5;
                        verts.push(
                            point(
                                cx + radius * innerRatio * Math.cos(innerA),
                                cy + radius * innerRatio * Math.sin(innerA)
                            )
                        );
                    }
                    return `polygon(${verts.join(', ')})`;
                };
                const startR = Math.max(2, R * 0.025);
                return [starPolygon(startR), starPolygon(R)];
            }
            default:
                return [
                    `circle(0% at ${point(cx, cy)})`,
                    `circle(${toRadius(maxRadius)} at ${point(cx, cy)})`
                ];
        }
    }

    const handleViewTransition = useCallback(
        (value: 'light' | 'dark' | 'system') => {
            const button = buttonRef.current;
            if (
                !button ||
                isTransitioningRef.current ||
                document.documentElement.dataset.themeSwitcherVt === 'active'
            ) 
                return;

            const viewportWidth = window.innerWidth;
            const viewportHeight = window.innerHeight;

            let x: number;
            let y: number;
            if (fromCenter) {
                x = viewportWidth / 2;
                y = viewportHeight / 2;
            } else {
                const { top, left, width, height } = 
                    button.getBoundingClientRect();
                x = left + width / 2;
                y = top + height / 2;
            }

            const maxRadius = Math.hypot(
                Math.max(x, viewportWidth - x),
                Math.max(y, viewportHeight - y)
            );

            const applyTheme = () => {
                applyThemeToDocument(value);
            };

            if (typeof document.startViewTransition !== 'function') {
                applyTheme();
                return;
            }

            const clipPath = getThemeTransitionClipPaths(
                shape,
                x,
                y,
                maxRadius,
                viewportWidth,
                viewportHeight
            );

            const root = document.documentElement;
            root.dataset.themeSwitcherVt = 'active';
            root.style.setProperty(
                '--theme-switcher-vt-duration',
                `${duration}ms`
            );
            root.style.setProperty(
                '--theme-switcher-vt-clip-from',
                clipPath[0]
            );
            root.style.setProperty('--theme-switcher-vt-clip-to', clipPath[1]);

            const cleanup = () => {
                isTransitioningRef.current = false;
                delete root.dataset.themeSwitcherVt;
                root.style.removeProperty('--theme-switcher-vt-duration');
                root.style.removeProperty('--theme-switcher-vt-clip-from');
                root.style.removeProperty('--theme-switcher-vt-clip-to');
            };

            isTransitioningRef.current = true;
            const transition = document.startViewTransition(() => {
                flushSync(applyTheme);
            });

            if (typeof transition?.finished?.finally === 'function') {
                transition.finished.finally(cleanup).catch(() => {});
            } else {
                cleanup();
            }

            const ready = transition?.ready;
            if (ready && typeof ready.then === 'function') {
                ready
                    .then(() => {
                        document.documentElement.animate(
                            {
                                clipPath: [clipPath[0], clipPath[1]]
                            },
                            {
                                duration,
                                easing:
                                    shape === 'star' ? 'linear' : 'ease-in-out',
                                fill: 'forwards',
                                pseudoElement: '::view-transition-new(root)'
                            }
                        );
                    })
                    .catch(() => {});
            }
        },
        [shape, fromCenter, duration]
    );
    // !SECTION: Functions

    // SECTION: Event Handlers
    const handleThemeToggle = useCallback(
        (value: 'light' | 'dark' | 'system') => {
            if (!value) return;

            setDataInLocalStorage('theme', value);

            if (value === 'system') {
                actions.setTheme(value);
                actions.setThemeShade(THEME.GUN_METAL); // Default to dark for system
            } else {
                actions.setTheme(value);
                actions.setThemeShade(
                    value === 'light' ? THEME.AMBER : THEME.GUN_METAL
                );
            }

            handleViewTransition(value);

            if (onThemeChange) {
                onThemeChange(
                    value === 'light' ? THEME.AMBER : THEME.GUN_METAL
                );
            }
        },
        [handleViewTransition, onThemeChange, actions]
    );
    // !SECTION: Event Handlers

    // SECTION: Side Effects
    useEffect(() => {
        const storedTheme = getDataFromLocalStorage('theme') as
            | 'light'
            | 'dark'
            | 'system'
            | null;
        if (storedTheme) {
            actions.setTheme(storedTheme);
            if (storedTheme === 'system') {
                actions.setThemeShade(THEME.GUN_METAL);
            } else {
                actions.setThemeShade(
                    storedTheme === 'light' ? THEME.AMBER : THEME.GUN_METAL
                );
            }
            applyThemeToDocument(storedTheme);
        } else {
            applyThemeToDocument(theme || 'light');
        }
    }, []);

    useEffect(() => {
        const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

        const handleSystemChange = () => {
            const currentTheme =
                (getDataFromLocalStorage('theme') as string) || theme;
            if (currentTheme === 'system') {
                applyThemeToDocument('system');
            }
        };

        mediaQuery.addEventListener('change', handleSystemChange);
        return () =>
            mediaQuery.removeEventListener('change', handleSystemChange);
    }, [theme]);

    useEffect(() => {
        if (isControlled) return;

        const updateTheme = () => {
            setInternalIsDark(
                document.documentElement.classList.contains('dark')
            );
        };

        updateTheme();

        const observer = new MutationObserver(updateTheme);
        observer.observe(document.documentElement, {
            attributes: true,
            attributeFilter: ['class']
        });

        return () => observer.disconnect();
    }, [isControlled]);
    // !SECTION: Side Effects

    return (
        <ToggleGroup
            ref={buttonRef}
            type="single"
            onValueChange={handleThemeToggle}
            value={theme}
        >
            <ToggleGroupItem value="light" aria-label="Light theme">
                <Sun className="text-text-primary" />
            </ToggleGroupItem>
            <ToggleGroupItem value="dark" aria-label="Dark theme">
                <Moon className="text-text-primary" />
            </ToggleGroupItem>
            <ToggleGroupItem value="system" aria-label="System theme">
                <Monitor className="text-text-primary" />
            </ToggleGroupItem>
        </ToggleGroup>
    );
}

'use client';

import { Text, TextVariant } from 'get-elementa-ui';
import gsap from 'gsap';
import { ArrowLeft, ArrowRight } from 'lucide-react';
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Button } from '../../components/button';

/**
 * This function renders a LightspunCurvedCarousel block component for the elementa-ui.
 *
 * @version 0.1.0
 * @author Aayush Goyal
 * @modified 2026-10-01
 */
export interface SlideItem {
    id: string | number;
    title?: string;
    subtitle?: string;
    description?: string;
    image?: string;
    [key: string]: any;
}

export interface LightspunCurvedCarouselProps<T extends SlideItem = SlideItem> {
    slides: T[];
    /** Custom render function for each card item */
    renderItem?: (item: T, index: number, isActive: boolean) => React.ReactNode;
    /** Cylinder radius in px (default: 900 for natural 3D curve) */
    radius?: number;
    /** Perspective depth in px (default: 1000) */
    perspective?: number;
    /** Total slots in cylinder ring to keep arc seamless (default: 21) */
    slidesInRing?: number;
    /** Height of individual slides (default: 380) */
    slideHeight?: number;
    /** Explicit slide width override. If omitted, calculated from arc length */
    slideWidth?: number;
    /** Spacing angle gap between slides (default: 1) */
    slideSpacing?: number;
    /** Enable auto rotation (default: false) */
    autoRotate?: boolean;
    /** Rotation speed in degrees per frame if autoRotate is true (default: 0.1) */
    rotationSpeed?: number;
    /** Pause auto rotation when hovering over carousel */
    pauseOnHover?: boolean;
    /** Delay in ms to resume rotation after unhovering (default: 1000) */
    resumeDelay?: number;
    /** Entrance animation mode: 'none' | 'fadeIn' | 'fadeUp' */
    entranceAnimation?: 'none' | 'fadeIn' | 'fadeUp';
    /** Entrance distance for 'fadeUp' mode */
    entranceDistance?: number;
    /** Enable edge fadeout gradient mask */
    fadeOut?: boolean;
    /** Show bottom manual controls & item detail panel (default: true) */
    showControls?: boolean;
    className?: string;
}

export function LightspunCurvedCarousel<T extends SlideItem = SlideItem>({
    slides,
    renderItem,
    radius = 900,
    perspective = 1000,
    slidesInRing = 12,
    slideHeight = 380,
    slideWidth,
    slideSpacing = 1,
    autoRotate = false,
    rotationSpeed = 0.1,
    pauseOnHover = true,
    resumeDelay = 1000,
    entranceAnimation = 'fadeUp',
    entranceDistance = 50,
    fadeOut = true,
    showControls = true,
    className = ''
}: LightspunCurvedCarouselProps<T>) {
    // SECTION: Constants and Variables
    const stageRef = useRef<HTMLDivElement>(null);
    const ringRef = useRef<HTMLDivElement>(null);
    const ringIndexRef = useRef<number>(0);
    // !SECTION: Constants and Variables

    // SECTION: States
    const [activeIndex, setActiveIndex] = useState<number>(0);

    // 1. Calculate & duplicate slides to meet the required ring density
    const totalTarget = Math.max(slidesInRing, slides.length);
    const multiplier = Math.ceil(totalTarget / (slides.length || 1));
    const normalizedSlides = Array.from({ length: multiplier }, () => slides)
        .flat()
        .slice(0, totalTarget);

    const totalSlideCount = normalizedSlides.length;
    const anglePerSlide = 360 / (totalSlideCount || 1);

    // Calculate proportional card width to avoid distorted aspect ratios
    const calculatedArcWidth =
        (anglePerSlide - slideSpacing) * (Math.PI / 180) * radius;
    const finalSlideWidth =
        slideWidth || Math.min(Math.max(calculatedArcWidth, 240), 320);

    // SECTION: Event Handlers
    // Rotate ring to target ring index using GSAP
    const rotateToRingIndex = useCallback(
        (targetRingIndex: number) => {
            if (!ringRef.current || slides.length === 0) return;

            ringIndexRef.current = targetRingIndex;

            // Calculate active original slide index
            const normalizedOriginalIndex =
                ((targetRingIndex % slides.length) + slides.length) %
                slides.length;
            setActiveIndex(normalizedOriginalIndex);

            const targetAngle = targetRingIndex * anglePerSlide;

            gsap.to(ringRef.current, {
                rotationY: targetAngle,
                duration: 0.7,
                ease: 'power2.out'
            });
        },
        [slides.length, anglePerSlide]
    );

    const nextSlide = useCallback(() => {
        rotateToRingIndex(ringIndexRef.current + 1);
    }, [rotateToRingIndex]);

    const prevSlide = useCallback(() => {
        rotateToRingIndex(ringIndexRef.current - 1);
    }, [rotateToRingIndex]);

    const goToSlide = useCallback(
        (targetOriginalIndex: number) => {
            const diff = targetOriginalIndex - activeIndex;
            rotateToRingIndex(ringIndexRef.current + diff);
        },
        [activeIndex, rotateToRingIndex]
    );
    // !SECTION: Event Handlers

    // SECTION: Side Effects
    // Initialize 3D Cylinder Layout
    useEffect(() => {
        if (!ringRef.current || totalSlideCount === 0) return;

        const ring = ringRef.current;
        const slideElements = Array.from(ring.children) as HTMLElement[];

        if (stageRef.current) {
            stageRef.current.style.width = `${finalSlideWidth}px`;
            stageRef.current.style.height = `${slideHeight}px`;
        }

        // Set initial 3D transform metrics for each card
        slideElements.forEach((slide, index) => {
            slide.style.width = `${finalSlideWidth}px`;
            slide.style.height = `${slideHeight}px`;

            gsap.set(slide, {
                rotateY: index * -anglePerSlide,
                transformOrigin: `50% 50% ${radius}px`,
                z: -radius,
                backfaceVisibility: 'hidden'
            });
        });

        // Auto Rotation Controller (if autoRotate is enabled)
        let speedController = { value: 0 };
        let speedTween: gsap.core.Tween | null = null;
        let resumeTimeout: NodeJS.Timeout | null = null;

        const startAutoRotation = () => {
            if (!autoRotate) return;
            if (speedTween) speedTween.kill();
            speedTween = gsap.to(speedController, {
                value: rotationSpeed,
                duration: 1.0,
                ease: 'power1.out'
            });
        };

        const stopAutoRotation = () => {
            if (speedTween) speedTween.kill();
            speedTween = gsap.to(speedController, {
                value: 0,
                duration: 0.6,
                ease: 'power1.out'
            });
        };

        const tickerCallback = () => {
            if (autoRotate && speedController.value !== 0 && ringRef.current) {
                gsap.set(ringRef.current, {
                    rotationY: `+=${speedController.value}`
                });
            }
        };

        // Entrance Animation Sequence
        const ctx = gsap.context(() => {
            if (entranceAnimation !== 'none') {
                let fromVars: gsap.TweenVars = { opacity: 0 };
                if (entranceAnimation === 'fadeUp') {
                    fromVars.y = entranceDistance;
                }

                gsap.from(slideElements, {
                    ...fromVars,
                    duration: 0.9,
                    stagger: 0.02,
                    ease: 'power2.out',
                    onComplete: () => {
                        if (autoRotate) startAutoRotation();
                    }
                });
            } else if (autoRotate) {
                startAutoRotation();
            }

            if (autoRotate) {
                gsap.ticker.add(tickerCallback);
            }
        });

        const handleMouseEnter = () => {
            if (!autoRotate || !pauseOnHover) return;
            if (resumeTimeout) clearTimeout(resumeTimeout);
            stopAutoRotation();
        };

        const handleMouseLeave = () => {
            if (!autoRotate || !pauseOnHover) return;
            resumeTimeout = setTimeout(() => {
                startAutoRotation();
            }, resumeDelay);
        };

        const containerEl = stageRef.current?.parentElement;
        if (containerEl && autoRotate) {
            containerEl.addEventListener('mouseenter', handleMouseEnter);
            containerEl.addEventListener('mouseleave', handleMouseLeave);
        }

        return () => {
            ctx.revert();
            if (autoRotate) gsap.ticker.remove(tickerCallback);
            if (resumeTimeout) clearTimeout(resumeTimeout);
            if (containerEl && autoRotate) {
                containerEl.removeEventListener('mouseenter', handleMouseEnter);
                containerEl.removeEventListener('mouseleave', handleMouseLeave);
            }
        };
    }, [
        totalSlideCount,
        radius,
        slideHeight,
        finalSlideWidth,
        anglePerSlide,
        autoRotate,
        rotationSpeed,
        pauseOnHover,
        resumeDelay,
        entranceAnimation,
        entranceDistance
    ]);

    // Keyboard Arrow Controls
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'ArrowLeft') prevSlide();
            if (e.key === 'ArrowRight') nextSlide();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [nextSlide, prevSlide]);
    // !SECTION: Side Effects

    const activeItem = slides[activeIndex];

    // SECTION: UI
    return (
        <div
            className={`relative flex w-full flex-col items-center py-8 ${className}`}
        >
            {/* 3D Viewport Stage */}
            <div
                className="pointer-events-none relative flex w-full items-center justify-center overflow-hidden py-4"
                style={{
                    maskImage: fadeOut
                        ? 'linear-gradient(to right, transparent 0%, black 12%, black 88%, transparent 100%)'
                        : 'none',
                    WebkitMaskImage: fadeOut
                        ? 'linear-gradient(to right, transparent 0%, black 12%, black 88%, transparent 100%)'
                        : 'none'
                }}
            >
                <div
                    ref={stageRef}
                    className="pointer-events-none relative flex items-center justify-center"
                    style={{
                        perspective: `${perspective}px`,
                        perspectiveOrigin: '50% 50%'
                    }}
                >
                    {/* Revolving Cylinder Ring */}
                    <div
                        ref={ringRef}
                        className="pointer-events-none relative flex h-full w-full items-center justify-center"
                        style={{ transformStyle: 'preserve-3d' }}
                    >
                        {normalizedSlides.map((slide, idx) => {
                            const originalIdx = idx % slides.length;
                            const isActive = originalIdx === activeIndex;

                            return (
                                <div
                                    key={`${slide.id}-${idx}`}
                                    onClick={() => goToSlide(originalIdx)}
                                    className={`border-stroke-active-accent-primary pointer-events-auto absolute inset-0 cursor-pointer overflow-hidden rounded-2xl border transition-all duration-300 ${
                                        isActive
                                            ? 'ring-stroke-active-accent-primary z-10 scale-100 shadow-2xl ring-2'
                                            : 'scale-95 opacity-70 hover:opacity-100'
                                    }`}
                                >
                                    {/* Custom Slot Renderer or Default Image Card */}
                                    {renderItem ? (
                                        renderItem(slide, originalIdx, isActive)
                                    ) : (
                                        <div className="from-bg-active-accent-primary to-bg-active-accent-secondary relative h-full w-full">
                                            {slide.image && (
                                                <img
                                                    src={slide.image}
                                                    alt={
                                                        slide.title ||
                                                        `Slide ${originalIdx}`
                                                    }
                                                    className="pointer-events-none h-full w-full object-cover"
                                                    loading="lazy"
                                                />
                                            )}
                                            {slide.title && (
                                                <div className="absolute inset-x-0 bottom-0 p-4 text-white">
                                                    <Text className="truncate font-sans text-xs font-semibold">
                                                        {slide.title}
                                                    </Text>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Manual Control Panel & Active Item Details */}
            {showControls && (
                <div className="mt-6 flex w-full max-w-3xl flex-col items-center gap-6 px-4">
                    {/* Active Item Details */}
                    {activeItem && (
                        <div className="text-center transition-all duration-300">
                            <span className="text-text-accent-secondary font-mono text-xs font-bold tracking-widest uppercase">
                                #{String(activeIndex + 1).padStart(2, '0')} /{' '}
                                {String(slides.length).padStart(2, '0')}
                            </span>
                            {activeItem.title && (
                                <Text
                                    variant={TextVariant.H3}
                                    className="text-text-accent-primary font-heading mx-auto mt-1"
                                >
                                    {activeItem.title}
                                </Text>
                            )}
                            {activeItem.description && (
                                <Text className="text-text-secondary mx-auto mt-1 max-w-md">
                                    {activeItem.description}
                                </Text>
                            )}
                        </div>
                    )}

                    {/* Navigation Controls */}
                    <div className="border-stroke-active-accent-secondary flex w-full items-center justify-between gap-4 border-t pt-4">
                        {/* Step Pills */}
                        <div className="flex items-center gap-1.5 overflow-x-auto py-1">
                            {slides.map((item, idx) => {
                                const isCurrent = idx === activeIndex;
                                return (
                                    <button
                                        key={item.id || idx}
                                        onClick={() => goToSlide(idx)}
                                        className={`rounded-full px-3 py-1 text-xs font-bold transition-all ${
                                            isCurrent
                                                ? 'bg-bg-active-accent-secondary text-text-primary shadow-md'
                                                : 'text-text-secondary hover:text-text-primary'
                                        }`}
                                    >
                                        #{String(idx + 1).padStart(2, '0')}
                                    </button>
                                );
                            })}
                        </div>

                        {/* Manual Arrow Buttons */}
                        <div className="flex shrink-0 items-center gap-2">
                            <Button
                                onClick={prevSlide}
                                aria-label="Previous Slide"
                                variant="outline"
                                className="text-text-accent-primary border-stroke-active-accent-primary rounded-full border bg-transparent p-2.5 transition-all active:scale-95"
                            >
                                <ArrowLeft className="h-4 w-4" />
                            </Button>
                            <Button
                                onClick={nextSlide}
                                aria-label="Next Slide"
                                className="text-text-accent-primary border-stroke-active-accent-primary rounded-full border bg-transparent p-2.5 transition-all active:scale-95"
                            >
                                <ArrowRight className="h-4 w-4" />
                            </Button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
    // !SECTION: UI
}

